import {
  Args, Int, Mutation, Resolver, Subscription,
} from '@nestjs/graphql';
import { PubSub } from 'graphql-subscriptions';

const pubSub = new PubSub();

@Resolver(() => Comment)
export class CommentsResolver {
  @Subscription(() => Comment)
  commentAdded() {
    return pubSub.asyncIterableIterator('commentAdded');
  }

  @Mutation(() => Comment)
  async addComment(@Args('postId', { type: () => Int }) postId: number) {
    const comment = this.commentsService.addComment(postId);
    pubSub.publish('commentAdded', { commentAdded: comment });
    return comment;
  }
}

